    @Test
    fun `creates new CrowdStrike asset with import timestamp`() {
        val savedAssetSlot = slot<Asset>()
        every { assetRepository.findPotentialCrowdStrikeMatches("server-1") } returns emptyList()
        every { assetRepository.save(capture(savedAssetSlot)) } answers {
            savedAssetSlot.captured.apply { id = 11L }
        }
        every {
            entityManager.find(Asset::class.java, 11L, jakarta.persistence.LockModeType.PESSIMISTIC_WRITE)
        } answers {
            savedAssetSlot.captured
        }

        service.importVulnerabilitiesForServer(batch("server-1"))

        assertThat(savedAssetSlot.captured.crowdStrikeLastImportedAt).isNotNull()
        assertThat(savedAssetSlot.captured.crowdStrikeHostname).isEqualTo("server-1")
    }

    @Test
    fun `keeps user display name and reuses same asset on later CrowdStrike import`() {
        val overriddenAt = LocalDateTime.now().minusHours(1)
        val existingAsset = Asset(
            id = 13L,
            name = "SAP production",
            crowdStrikeHostname = "server-3.example.com",
            nameOverriddenAt = overriddenAt,
            nameOverriddenBy = "asset-owner",
            type = "SERVER",
            owner = "CrowdStrike Import",
            cloudInstanceId = "i-server-3"
        )

        every { assetRepository.findByCloudInstanceIdIgnoreCase("i-server-3") } returns existingAsset
        every { assetRepository.update(existingAsset) } returns existingAsset
        every {
            entityManager.find(Asset::class.java, 13L, jakarta.persistence.LockModeType.PESSIMISTIC_WRITE)
        } returns existingAsset

        val result = service.importVulnerabilitiesForServer(
            batch(
                hostname = "server-3.example.com",
                cloudInstanceId = "i-server-3"
            )
        )

        assertThat(result.assetCreated).isFalse()
        assertThat(existingAsset.name).isEqualTo("SAP production")
        assertThat(existingAsset.crowdStrikeHostname).isEqualTo("server-3.example.com")
        assertThat(existingAsset.nameOverriddenAt).isEqualTo(overriddenAt)
        verify(exactly = 0) { assetRepository.save(any()) }
    }

