        } finally {
            assertThat(post("$endpoint/$runId/finish?successful=false", adminToken).body()!!["status"]).isEqualTo("FAILED")
        }
        denied("$endpoint/$runId/heartbeat", adminToken, HttpStatus.CONFLICT)
    }
